/* ---- View switch: list only / map only / split ---- */
.app-grid {
  display: grid;
  gap: var(--zh-column-gap);
  align-items: start;
}

/* Single-column layouts (phones and tablets) put the map first: a map explorer
   whose map sits below a 40-entry result list is unusable on a phone. The DOM
   order stays list-first for screen readers and the tab order, and the map
   keeps its own keyboard controls. */
@media (max-width: 1023px) {
  .app-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .app-mapwrap {
    order: -1;
  }
}

.app-view--map .app-grid {
  grid-template-columns: minmax(0, 1fr);
}

.app-view--map .app-side {
  display: none;
}

.app-view--map .app-map,
.app-view--map .app-mapwrap {
  /* The map container must stay positioned: its tiles, extents and markers are
     absolutely positioned children (see .map-layer in map.js). A `position:
     static` override made them escape the box — they painted over the intro
     and produced ~80 px of horizontal page overflow. */
  position: relative;
  top: auto;
  height: min(78vh, 760px);
}

/* In map-only view the map is the page: the intro and its facts would push it
   below the fold again. The toolbar keeps the way back to the other views. */
.app-view--map .app-intro {
  display: none;
}

.app-view--list .app-grid {
  grid-template-columns: minmax(0, 1fr);
}

.app-view--list .app-mapwrap,
.app-view--list .app-map__skip,
.app-view--list .app-map__hint {
  display: none;
}

.app-view--list .app-result-list {
  /* `minmax(320px, …)` overflows the 320 px cantonal breakpoint (the shell has
     12 px gutters, so only ~296 px remain). `min(320px, 100%)` keeps the
     multi-column list without a horizontal scrollbar. */
  grid-template-columns: repeat(auto-fill, minmax(min(320px, 100%), 1fr));
}
