  .zh-header__note-long {
    display: none;
  }
  .zh-header__note-short {
    display: inline;
  }
  .zh-header__main {
    padding-block: var(--zh-size-tiny);
    gap: var(--zh-size-tiny);
  }
  .zh-header__bar-inner {
    padding-block: 2px;
  }
  .app-main {
    padding-block: var(--zh-size-tiny) 0;
  }
  .app-intro {
    padding: var(--zh-size-tiny) var(--zh-size-regular);
    margin-bottom: var(--zh-size-tiny);
  }
  /* Cantonal type curve for h1 at the smallest breakpoint ($fontSizeCurves
     huge/tiny = 28px) — the 32px base is meant for ≥400px. */
  .app-intro .zh-heading--1 {
    font-size: var(--zh-font-small-big);
    margin-bottom: var(--zh-size-tiny);
  }
  /* Orientation text stays readable but does not push the map off the screen:
     the short variant ends on its own at 320–430 px, so the clamp is a safety
     net rather than the thing that ends the sentence. The full wording lives
     in “Über das Projekt” and the result list. */
  .app-intro__lead-long {
    display: none;
  }
  .app-intro__lead-short {
    display: inline;
  }
  .app-intro .zh-lead {
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
    margin-bottom: var(--zh-size-tiny);
  }
  .app-intro__more {
    display: block;
    margin: 0 0 var(--zh-size-tiny);
    font-size: var(--zh-font-small);
  }
  .zh-facts {
    /* Stock figures stay complete but compact: two columns instead of one
       clipped row. A scrollable row looked broken on a phone (the fourth
       figure, “IIIF-Bildservice”, was cut mid-word with no scroll affordance),
       and a single stacked column would push the map far down; two columns are
       readable at 320 px and cost one short line. */
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--zh-size-small-regular) var(--zh-size-regular);
    padding-bottom: 4px;
  }
  /* On a phone the *hero* strip is removed: the same figures now stand in the
     two-column list inside “Über das Projekt” (#about-facts, filled from the
     same data path in main.js), so the first screen belongs to the map. */
  .app-intro > .zh-facts {
    display: none;
  }
  .zh-facts--about {
    display: grid;
    margin-bottom: var(--zh-size-small-regular);
  }
  .zh-facts > li {
    min-width: 0;
  }
  /* The source tags repeat verbatim in “Quellen und Rechte” (#source-list), so
     the smallest breakpoint keeps the way to the map short instead. */
  #intro-tags {
    display: none;
  }
  .app-intro__more-long {
    display: none;
  }
  .app-intro__more-short {
    display: inline;
  }
  /* Toolbar: keep it to three compact rows on a 320 px phone. The “Ansicht”
     and “Sortierung” labels stay in the accessibility tree (the chips and the
     select keep their accessible names) but stop eating horizontal room, so the
     three view chips fit one row. */
  .app-toolbar {
    padding: var(--zh-size-tiny) var(--zh-size-small-regular);
    gap: var(--zh-size-tiny);
    margin-bottom: var(--zh-size-tiny);
  }
  .app-toolbar__group {
    flex-wrap: wrap;
  }
  .app-toolbar .zh-label {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }
  .app-toolbar__label {
    font-size: var(--zh-font-regular);
  }

  /* Quick picks (search) and quick year ranges stay on one scrollable line
     instead of wrapping into a tall block above the map. */
  #place-quick,
  .zh-quickranges {
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: thin;
    padding-bottom: 2px;
  }
  #place-quick > *,
  .zh-quickranges > * {
    flex: 0 0 auto;
  }
}

/* Below the cantonal 400 px breakpoint the brand claim goes as well: the name
   stays, and the claim repeats the page title while costing a line above the
   map. The claim remains in the document title and the meta description. */
@media (max-width: 399px) {
  .zh-brand__claim {
    display: none;
  }
}

