#!/usr/bin/env node
/** Scratch probe: measure the 320 px first screen and test candidate CSS tweaks. */
import { spawn } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const BASE_URL = (process.argv[2] || 'http://127.0.0.1:8787').replace(/\/$/, '');
const OUT = process.argv[3] || '/tmp/probe320';
const PORT = 9333;
await mkdir(OUT, { recursive: true });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

class CDP {
  constructor(ws) {
    this.ws = ws; this.id = 0; this.pending = new Map();
    ws.addEventListener('message', (event) => {
      const m = JSON.parse(event.data);
      if (m.id && this.pending.has(m.id)) {
        const { resolve, reject } = this.pending.get(m.id);
        this.pending.delete(m.id);
        if (m.error) reject(new Error(m.error.message)); else resolve(m.result);
      }
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
      setTimeout(() => { if (this.pending.delete(id)) reject(new Error(`${method} timeout`)); }, 30000);
    });
  }
  async eval(expression) {
    const { result, exceptionDetails } = await this.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (exceptionDetails) throw new Error(exceptionDetails.exception?.description || exceptionDetails.text);
    return result?.value;
  }
  async waitFor(expression, timeout = 20000) {
    const deadline = Date.now() + timeout;
    while (Date.now() < deadline) {
      try { const v = await this.eval(expression); if (v) return v; } catch { /* retry */ }
      await sleep(200);
    }
    throw new Error(`timeout: ${expression}`);
  }
  async screenshot(file) {
    const { data } = await this.send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
    await writeFile(file, Buffer.from(data, 'base64'));
  }
}

const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--hide-scrollbars',
  '--window-size=320,640', `--remote-debugging-port=${PORT}`,
  `--user-data-dir=${path.join(os.tmpdir(), `probe320-${process.pid}`)}`, 'about:blank',
], { stdio: ['ignore', 'ignore', 'pipe'] });
const errs = [];
chrome.stderr.on('data', (d) => errs.push(d.toString()));

let wsUrl;
const deadline = Date.now() + 30000;
while (Date.now() < deadline) {
  try {
    const res = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' });
    if (res.ok) { const t = await res.json(); if (t.webSocketDebuggerUrl) { wsUrl = t.webSocketDebuggerUrl; break; } }
  } catch { /* retry */ }
  await sleep(300);
}
if (!wsUrl) { console.error('no chrome', errs.join('').slice(-500)); process.exit(1); }

const ws = new WebSocket(wsUrl);
await new Promise((resolve) => ws.addEventListener('open', resolve));
const cdp = new CDP(ws);
await cdp.send('Page.enable');
await cdp.send('Runtime.enable');

const MEASURE = `(() => {
  const box = (sel) => { const n = document.querySelector(sel); if (!n) return null; const r = n.getBoundingClientRect(); return { top: Math.round(r.top + scrollY), h: Math.round(r.height), bottom: Math.round(r.bottom + scrollY) }; };
  const map = document.querySelector('#map');
  const mr = map?.getBoundingClientRect();
  return {
    viewport: [innerWidth, innerHeight],
    scrollHeight: document.documentElement.scrollHeight,
    overflowX: document.documentElement.scrollWidth - innerWidth,
    header: box('.zh-header'),
    intro: box('.app-intro'),
    toolbar: box('.app-toolbar'),
    mapwrap: box('.app-mapwrap'),
    mapTop: mr ? Math.round(mr.top + scrollY) : null,
    mapVisible: mr ? Math.max(0, Math.min(innerHeight, mr.bottom) - Math.max(0, mr.top)) : null,
    rows: document.querySelectorAll('#result-list > li').length,
  };
})()`;

async function load(width, height) {
  await cdp.send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 2, mobile: true });
  await cdp.send('Page.navigate', { url: `${BASE_URL}/` });
  await cdp.waitFor(`document.querySelectorAll('#result-list > li').length > 0`);
  await sleep(400);
}

const VARIANTS = {
  baseline: '',
  A_hideNote360: `@media (max-width:399px){.zh-header__bar{display:none}}`,
  B_leanTop: `@media (max-width:399px){
    .zh-header__bar{display:none}
    .zh-brand__logo{width:40px;height:auto}
    .zh-header__main{padding-block:4px;gap:4px}
    .app-intro .zh-lead{display:none}
    .app-intro__more{margin-bottom:4px}
    .app-intro{padding:8px 12px}
    .app-main{padding-block:4px 0}
  }`,
  C_leanTopNoHero: `@media (max-width:399px){
    .zh-header__bar{display:none}
    .zh-brand__logo{width:40px;height:auto}
    .zh-header__main{padding-block:4px;gap:4px}
    .app-intro{display:none}
    .app-main{padding-block:4px 0}
  }`,
  D_reorder: `@media (max-width:399px){
    .zh-header__bar{display:none}
    .app-main{display:flex;flex-direction:column}
    .app-toolbar{order:1}
    .app-grid{order:2}
    .app-intro{order:3}
  }`,
};

for (const [name, css] of Object.entries(VARIANTS)) {
  await load(320, 640);
  if (css) {
    await cdp.eval(`(() => { const s = document.createElement('style'); s.id='probe-css'; s.textContent = ${JSON.stringify(css)}; document.head.append(s); return true; })()`);
    await sleep(300);
  }
  const m = await cdp.eval(MEASURE);
  console.log(name.padEnd(16), JSON.stringify(m));
  await cdp.screenshot(path.join(OUT, `${name}.png`));
}

ws.close();
chrome.kill('SIGKILL');

