#!/usr/bin/env node
/** Probe: keyboard path through the comparison view (pin → open → trap → Esc). */
import { spawn } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const BASE_URL = (process.argv[2] || 'http://127.0.0.1:8787').replace(/\/$/, '');
const OUT = process.argv[3] || '/tmp/probe-compare-kb';
const PORT = 9336;
await mkdir(OUT, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

class CDP {
  constructor(ws) { this.ws = ws; this.id = 0; this.pending = new Map(); ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && this.pending.has(m.id)) { const { resolve, reject } = this.pending.get(m.id); this.pending.delete(m.id); if (m.error) reject(new Error(m.error.message)); else resolve(m.result); } }); }
  send(method, params = {}) { const id = ++this.id; return new Promise((resolve, reject) => { this.pending.set(id, { resolve, reject }); this.ws.send(JSON.stringify({ id, method, params })); setTimeout(() => { if (this.pending.delete(id)) reject(new Error(`${method} timeout`)); }, 30000); }); }
  async eval(expression) { const { result, exceptionDetails } = await this.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }); if (exceptionDetails) throw new Error(exceptionDetails.exception?.description || exceptionDetails.text); return result?.value; }
  async waitFor(expression, timeout = 20000) { const deadline = Date.now() + timeout; let last; while (Date.now() < deadline) { try { last = await this.eval(expression); if (last) return last; } catch (err) { last = err.message; } await sleep(200); } throw new Error(`timeout: ${expression} last=${JSON.stringify(last)}`); }
  async screenshot(file) { const { data } = await this.send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false }); await writeFile(file, Buffer.from(data, 'base64')); }
  async key(key, { code, keyCode, shift = false } = {}) {
    const info = { code, windowsVirtualKeyCode: keyCode, nativeVirtualKeyCode: keyCode, modifiers: shift ? 8 : 0 };
    await this.send('Input.dispatchKeyEvent', { type: 'rawKeyDown', key, ...info });
    await this.send('Input.dispatchKeyEvent', { type: 'keyUp', key, ...info });
  }
  async tab(shift = false) { await this.key('Tab', { code: 'Tab', keyCode: 9, shift }); await sleep(60); }
  async escape() { await this.key('Escape', { code: 'Escape', keyCode: 27 }); await sleep(150); }
  async enter() {
    await this.send('Input.dispatchKeyEvent', { type: 'rawKeyDown', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, nativeVirtualKeyCode: 13 });
    await this.send('Input.dispatchKeyEvent', { type: 'char', text: '\r', unmodifiedText: '\r', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, nativeVirtualKeyCode: 13 });
    await this.send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, nativeVirtualKeyCode: 13 });
    await sleep(150);
  }
  async click(selector) {
    const box = await this.eval(`(() => { const n = document.querySelector(${JSON.stringify(selector)}); if (!n) return null; n.scrollIntoView({ block: 'center', behavior: 'instant' }); const r = n.getBoundingClientRect(); return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) }; })()`);
    if (!box) throw new Error(`no ${selector}`);
    await this.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: box.x, y: box.y, button: 'left', clickCount: 1 });
    await this.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: box.x, y: box.y, button: 'left', clickCount: 1 });
    await sleep(200);
  }
}

const chrome = spawn('chromium', ['--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--hide-scrollbars', '--window-size=1440,960', `--remote-debugging-port=${PORT}`, `--user-data-dir=${path.join(os.tmpdir(), `probe-cmpkb-${process.pid}`)}`, 'about:blank'], { stdio: ['ignore', 'ignore', 'pipe'] });
let wsUrl;
const deadline = Date.now() + 30000;
while (Date.now() < deadline) {
  try { const res = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' }); if (res.ok) { const t = await res.json(); if (t.webSocketDebuggerUrl) { wsUrl = t.webSocketDebuggerUrl; break; } } } catch { /* retry */ }
  await sleep(300);
}
if (!wsUrl) { console.error('no chrome'); process.exit(1); }
const ws = new WebSocket(wsUrl);
await new Promise((r) => ws.addEventListener('open', r));
const cdp = new CDP(ws);
await cdp.send('Page.enable');
await cdp.send('Runtime.enable');
await cdp.send('Network.enable');
await cdp.send('Network.setCacheDisabled', { cacheDisabled: true });

// Two records with a manifest, straight from the seed.
const ids = await cdp.eval(`fetch('/data/records.json').then(r => r.json()).then(d => d.records.filter(r => r.iiifManifest).slice(0, 2).map(r => r.id))`).catch(() => null);
let [id1, id2] = ids ?? [];
if (!id1) {
  await cdp.send('Page.navigate', { url: `${BASE_URL}/` });
  await cdp.waitFor(`document.querySelectorAll('#result-list > li').length > 0`);
  [id1, id2] = await cdp.eval(`[...document.querySelectorAll('#result-list button[data-record-id]')].slice(0, 2).map(b => b.dataset.recordId)`);
